        const completed = Number(phase?.completedOperations);
        const operationEvent = ["operation", "operation-start", "layout-start"].includes(phase?.phase);
        const shouldNotify = !operationEvent
          || completed <= 1
          || completed % 10 === 0
          || (Number.isFinite(Number(phase?.operationCount)) && completed >= Number(phase.operationCount));
        if (shouldNotify) notify(`正在执行：${phase.label}${phase?.phase === "operation" && Number.isFinite(completed) ? `（${completed}/${phase.operationCount}）` : ""}；草稿画板保持可见，可随时暂停`);
